<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php';
$pdo = db();
$stats = ['projects' => (int)$pdo->query('SELECT COUNT(*) FROM projects')->fetchColumn(), 'published' => (int)$pdo->query("SELECT COUNT(*) FROM projects WHERE status='published'")->fetchColumn(), 'new_messages' => (int)$pdo->query("SELECT COUNT(*) FROM contact_messages WHERE status='new'")->fetchColumn(), 'total_messages' => (int)$pdo->query('SELECT COUNT(*) FROM contact_messages')->fetchColumn()];
$recent = $pdo->query('SELECT id,name,email,service,status,created_at FROM contact_messages ORDER BY created_at DESC LIMIT 6')->fetchAll();
$pageTitle = 'Dashboard'; require __DIR__ . '/includes/header.php';
?><section class="stat-cards"><article><small>ALL PROJECTS</small><b><?= $stats['projects'] ?></b><span><?= $stats['published'] ?> published</span></article><article><small>NEW ENQUIRIES</small><b><?= $stats['new_messages'] ?></b><span><?= $stats['total_messages'] ?> total messages</span></article></section><section class="admin-panel"><div class="panel-heading"><div><h2>Recent enquiries</h2><p>Latest messages submitted from the public website.</p></div><a href="/admin/messages.php">View all →</a></div><?php if (!$recent): ?><p class="empty-admin">No messages yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>CONTACT</th><th>SERVICE</th><th>STATUS</th><th>RECEIVED</th></tr></thead><tbody><?php foreach ($recent as $message): ?><tr><td><strong><?= e($message['name']) ?></strong><small><?= e($message['email']) ?></small></td><td><?= e($message['service']) ?></td><td><span class="status status-<?= e($message['status']) ?>"><?= e($message['status']) ?></span></td><td><?= e($message['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php require __DIR__ . '/includes/footer.php'; ?>
